get_doc.beforeRequest:
var docIdOf = (raw) => {
  var text = String(raw).trim();
  if (!/^https?:\/\//i.test(text)) {
    if (!/^[A-Za-z0-9_-]+$/.test(text)) throw new Error('"' + text + '" is not a valid Coda doc ID. Pass the ID (for example AbC123xyZ) or the doc\'s browser link.');
    return text;
  }
  var link = /^https?:\/\/(?:[^@\/?#]*@)?([^:\/?#]*)(?::\d*)?([^?#]*)/i.exec(text);
  var host = link ? link[1].toLowerCase().replace(/^www\./, '') : '';
  if (host !== 'coda.io' && host !== 'docs.superhuman.com') throw new Error('"' + text + '" is not a Coda doc link (expected coda.io or docs.superhuman.com).');
  var segments = link[2].split('/').filter((segment) => segment.length > 0);
  var slug = segments[0] === 'd' ? segments[1] : undefined;
  var cut = slug ? slug.lastIndexOf('_d') : -1;
  var id = slug && cut >= 0 ? slug.slice(cut + 2) : undefined;
  if (!id || !/^[A-Za-z0-9_-]+$/.test(id)) throw new Error('Could not find a doc ID in "' + text + '". Paste a link like https://coda.io/d/My-Doc_dAbC123 or the doc ID itself.');
  return id;
};
var start = request.url.indexOf('/apis/v1/') + '/apis/v1/'.length;
var parts = request.url.slice(start).split('/').map((part) => decodeURIComponent(part).trim());
parts.forEach((part) => { if (part === '.' || part === '..') throw new Error('"' + part + '" is not a valid Coda ID or name.'); });
if (parts[0] === 'docs' && parts.length > 1) parts[1] = docIdOf(parts[1]);
request.url = request.url.slice(0, start) + parts.map(encodeURIComponent).join('/');
return request;

